{"path": "/tmp/sv-a868a868dfec4662bab58f18131b5863/Components/Pages/Board/KanbanColumn.razor", "file_text": "@namespace sv_a868a868dfec4662bab58f18131b5863.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="() => HandleMoveLeft(task)"
                      OnMoveRight="() => HandleMoveRight(task)" />
        }
    </div>
    <div class="column-footer">
        @if (showAddForm)
        {
            <AddTaskForm OnTaskCreated="HandleTaskCreated" OnCancel="HideForm" />
        }
        else
        {
            <button class="btn-add-task" @onclick="ShowForm">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = string.Empty;
    [Parameter, EditorRequired] public string Status { get; set; } = string.Empty;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<(int TaskId, string Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<TaskItem> OnAddTask { get; set; }

    private bool showAddForm;

    private void ShowForm() => showAddForm = true;
    private void HideForm() => showAddForm = false;

    private async Task HandleMoveLeft(TaskItem task)
    {
        await OnMoveTask.InvokeAsync((task.Id, "left"));
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        await OnMoveTask.InvokeAsync((task.Id, "right"));
    }

    private async Task HandleTaskCreated(TaskItem formData)
    {
        var taskWithStatus = formData with { Status = Status };
        await OnAddTask.InvokeAsync(taskWithStatus);
        showAddForm = false;
    }
}
"}

