+    border-radius: 4px;
+    font-size: 0.9rem;
+}
+
+.form-actions {
+    display: flex;
+    gap: 0.5rem;
+}
+
+.btn-save {
+    flex: 1;
+    padding: 0.4rem;
+    background: #0d6efd;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-save:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-cancel {
+    flex: 1;
+    padding: 0.4rem;
+    background: #6c757d;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.loading-message {
+    text-align: center;
+    color: #6c757d;
+    padding: 2rem;
+}
+
+.error-message {
+    background: #f8d7da;
+    color: #842029;
+    padding: 1rem;
+    border-radius: 6px;
+    margin-bottom: 1rem;
+}
+
+.error-message button {
+    margin-top: 0.5rem;
+    padding: 0.4rem 1rem;
+    background: #842029;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
